const id = $json.body.campaign_id;
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (typeof id !== 'string' || !uuidRe.test(id)) {
  throw new Error('campaign_id missing or not a valid UUID: ' + JSON.stringify(id));
}
return [{ json: { campaign_id: id } }];

const row = $('Get campaign').item.json;
const client = $json;
if (!row || !row.id) throw new Error('Campaign row not found.');
const rawCustomerId = row.google_ads_customer_id;
if (!rawCustomerId) {
  throw new Error('campaigns.google_ads_customer_id is not set â€” the client needs a Google Ads account already linked under the MCC before this can run.');
}
// Google Ads REST paths need digits only â€” strip dashes/spaces in case
// they slipped in upstream (e.g. someone pasted '161-685-9870' as-is).
const customerId = String(rawCustomerId).replace(/[^0-9]/g, '');

// Accounts this OAuth login can access directly (NOT as an MCC child) â€”
// sending login-customer-id for these fails with USER_PERMISSION_DENIED
// because they aren't actually linked under the MCC. Mirrors
// DIRECT_ACCESS_CUSTOMER_IDS in code/sync_all_clients.py. Every new client
// onboarded through the intake form is a real MCC child and gets the
// header normally.
const DIRECT_ACCESS_CUSTOMER_IDS = ['3534195221'];
const mccCustomerId = $('Get Google Ads credentials').item.json.mcc_customer_id;
const loginCustomerId = DIRECT_ACCESS_CUSTOMER_IDS.includes(customerId) ? '' : mccCustomerId;

return [{
  json: {
    campaignRowId: row.id,
    customerId,
    loginCustomerId,
    campaignName: row.campaign_name,
    primaryKeyword: row.primary_keyword,
    goal: row.goal,
    dailyBudgetUsd: Number(row.daily_budget_usd),
    biddingStrategy: (row.bidding_strategy || '').toLowerCase(),
    languages: row.languages || ['English'],
    targetedLocations: row.targeted_locations || [],
    adSchedule: (row.ad_schedule || '24 hours').toLowerCase(),
    businessName: client.business_name,
    websiteUrl: client.website_url || 'https://example.com',
  },
}];

