const budgetResource = $('Create budget').item.json.results[0].resourceName;
const ctx = $('Prepare context').item.json;
const strategy = ctx.biddingStrategy;

let biddingField;
if (strategy === 'maximize clicks') {
  biddingField = { targetSpend: {} };
} else if (strategy === 'manual cpc') {
  biddingField = { manualCpc: { enhancedCpcEnabled: false } };
} else {
  // Maximize Conversions, or Target CPA (no target value collected in the
  // intake form yet) â€” falls back to Maximize Conversions, same as the
  // Python version did.
  biddingField = { maximizeConversions: {} };
}

const body = {
  operations: [{
    create: {
      name: ctx.campaignName,
      campaignBudget: budgetResource,
      status: 'PAUSED',
      advertisingChannelType: 'SEARCH',
      networkSettings: {
        targetGoogleSearch: true,
        targetSearchNetwork: false,
        targetContentNetwork: false,
        targetPartnerSearchNetwork: false,
      },
      containsEuPoliticalAdvertising: 'DOES_NOT_CONTAIN_EU_POLITICAL_ADVERTISING',
      geoTargetTypeSetting: { positiveGeoTargetType: 'PRESENCE' },
      ...biddingField,
    },
  }],
};

return [{ json: { body } }];

