const suggestions = $json.geoTargetConstantSuggestions || [];
const seen = new Map();
for (const s of suggestions) {
  const term = s.searchTerm;
  if (term && !seen.has(term)) {
    seen.set(term, s.geoTargetConstant.resourceName);
  }
}
const geoResources = [...seen.values()];
if (geoResources.length === 0) {
  throw new Error('No geo target constants resolved for: ' + JSON.stringify($('Prepare context').item.json.targetedLocations));
}

const ctx = $('Prepare context').item.json;
const campaignResource = $('Create campaign').item.json.results[0].resourceName;

const languageMap = {
  english: 'languageConstants/1000',
  french: 'languageConstants/1002',
  spanish: 'languageConstants/1003',
};

const schedulePresets = {
  '24 hours': ['MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY'].map(d => [d, 0, 0, 24, 0]),
  'business hours (mon-fri 9am-6pm)': ['MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY'].map(d => [d, 9, 0, 18, 0]),
};
const schedule = schedulePresets[ctx.adSchedule] || schedulePresets['24 hours'];

const operations = [];

for (const geoResource of geoResources) {
  operations.push({ create: { campaign: campaignResource, location: { geoTargetConstant: geoResource } } });
}

for (const lang of ctx.languages) {
  const resource = languageMap[(lang || '').toLowerCase()] || languageMap.english;
  operations.push({ create: { campaign: campaignResource, language: { languageConstant: resource } } });
}

for (const [day, startHour, startMinute, endHour, endMinute] of schedule) {
  operations.push({
    create: {
      campaign: campaignResource,
      adSchedule: {
        dayOfWeek: day,
        startHour,
        startMinute: 'ZERO',
        endHour,
        endMinute: 'ZERO',
      },
    },
  });
}

return [{ json: { body: { operations } } }];

