const ctx = $('Prepare context').item.json;
const { businessName, primaryKeyword, goal, websiteUrl } = ctx;
const titleKeyword = primaryKeyword.replace(/\b\w/g, c => c.toUpperCase());

const pinned = [titleKeyword, businessName, `${titleKeyword} Experts`];
const unpinned = [
  `Contact ${businessName} Today`,
  'Free Consultation Available',
  'No Commitment Required',
  'Trusted Local Service',
  'Get Started Today',
  `${goal.charAt(0).toUpperCase()}${goal.slice(1)} Made Simple`,
  'Book Online Today',
  'Serving Your Area',
];
const descriptions = [
  `${businessName} offers ${primaryKeyword}. Contact us today to get started.`,
  'Free consultation, no commitment required. See how we can help.',
  'Trusted, local, and ready to help. Reach out to learn more.',
  `Looking for ${primaryKeyword}? ${businessName} is here to help.`,
];

const headlines = [
  ...pinned.map(text => ({ text: text.slice(0, 30), pinnedField: 'HEADLINE_1' })),
  ...unpinned.map(text => ({ text: text.slice(0, 30) })),
];
const descAssets = descriptions.map(text => ({ text: text.slice(0, 90) }));

const body = {
  operations: [{
    create: {
      adGroup: $('Create ad group').item.json.results[0].resourceName,
      status: 'PAUSED',
      ad: {
        finalUrls: [websiteUrl],
        responsiveSearchAd: { headlines, descriptions: descAssets },
      },
    },
  }],
};

return [{ json: { body } }];

